-- WP-M2-20 / LH-6.5-OPT-008: Gewichte der Mehrzielbewertung als neue Dienstparameter im Konfigurationsregister (Offener Punkt 18: im Katalog kataloge.csv nicht enthalten).
-- Vorläufige Festlegung (Planungsannahme, Fachfreigabe und Produktionswerte stehen unter D-05 aus): ganze Zahlen 0..100, Standard 40/20/25/15; die Summe muss größer 0 sein
-- (diese Querprüfung leistet die Bewertungsfunktion, das Schema je Parameter kennt nur den Bereich). Die Parameter werden der Startversion '1' hinzugefügt (nur INSERT; die
-- Unveränderlichkeit sperrt UPDATE/DELETE): Version '1' trägt bisher nur Planungsstand-Werte, keine freigegebene Produktion. Gemeinsame Quelle: vertraege/schemas/opt_weight_*.v1.schema.json.
SET search_path = taktovia, public;

INSERT INTO policy_schema(schema_version, parameter, json_schema) VALUES
